def p(*xs):return ''.join(f'<p>{x}</p>' for x in xs)
def table(headers,rows):return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def bullets(xs):return '<ul>'+''.join(f'<li>{x}</li>' for x in xs)+'</ul>'
def note(title,text):return f'<aside class="callout"><strong>{title}</strong><p>{text}</p></aside>'
def code(s):return '<pre><code>'+escape(s)+'</code></pre>'
def questions(t,rows):return table([t('Test question','测试问题'),t('Method / evidence','方法 / 证据'),t('Interpretation','结果解释')],rows)

