def tool_catalog(lang):
 t=lambda en,zh:zh if lang=='zh' else en
 body='<div class="tool-filter"><label for="tool-search">'+t('Find a tool or purpose','查找工具或用途')+'</label><input id="tool-search" type="search" placeholder="'+t('Name, purpose or keyword','名称、用途或关键词')+'"><label for="tool-category">'+t('Direction','方向')+'</label><select id="tool-category"><option value="all">'+t('All directions','所有方向')+'</option>'+''.join(f'<option value="{key}">{t(en,zh)}</option>' for key,en,zh in CATEGORIES)+'</select><p id="tool-count" role="status" aria-live="polite">'+t(f'{len(TOOLS)} tools',f'{len(TOOLS)} 项工具')+'</p></div><div class="tool-grid">'
 for name,cat,source,en,zh,limit_en,limit_zh in TOOLS:
  category=next((e,z) for c,e,z in CATEGORIES if c==cat)
  body+=f'<article class="tool-card" data-category="{cat}"><span class="eyebrow">{t(*category)}</span><h3>{name}</h3><p>{t(en,zh)}</p><small>{t(limit_en,limit_zh)}</small><a href="{SOURCES[source][2]}" target="_blank" rel="noopener noreferrer">'+t('Official documentation ↗','官方文档 ↗')+'</a></article>'
 return body+'</div>'
